import type { ReactNode } from 'react'
import type { StyleProp, ViewStyle } from 'react-native'
import type { RadiusKey } from '@ondai/tokens'
import { useMotion, useTheme } from '@ondai/tokens/react'
import { BorderBeam as BeamEngine } from './engine'
import type { BorderBeamColorVariant, BorderBeamSize } from './types'

export interface BorderBeamProps {
  children: ReactNode
  /** Light travels while true (the model is working); fades out when it turns false. */
  active?: boolean
  /** libraries.dev's palettes; `mono` is the quiet one. */
  tone?: BorderBeamColorVariant
  /** `md` circles the whole border, `sm` is a tighter beam for chips, `line` runs along the bottom edge, `pulse-*` breathe. */
  size?: BorderBeamSize
  /** Match the wrapped surface's corner radius. */
  radius?: RadiusKey | number
  /** 0 to 1. */
  strength?: number
  style?: StyleProp<ViewStyle>
}

/** Seconds per lap: a little slower than libraries.dev's 1.96 s, so a long generation reads calm. */
const LAP = { md: 2.6, sm: 2.2, line: 3.4, 'pulse-inner': 2.6, 'pulse-outside': 2.6 } as const

/**
 * A light that travels around a card's border while the on-device model works.
 * The shader and its tuning are libraries.dev's border beam (MIT); Ondai sets
 * a calmer lap, theme-aware light/dark, token radii, and a still frame when the OS asks for reduced motion.
 */
export function BorderBeam({ children, active = true, tone = 'colorful', size = 'md', radius = 'lg', strength = 1, style }: BorderBeamProps) {
  const t = useTheme()
  const motion = useMotion()
  const r = typeof radius === 'number' ? radius : t.radii[radius]
  return (
    <BeamEngine
      active={active}
      size={size}
      colorVariant={tone}
      theme={t.scheme}
      borderRadius={r}
      strength={strength}
      // Reduced motion: the beam holds still and the colors stop drifting.
      duration={motion.enabled ? LAP[size] : 1e9}
      staticColors={!motion.enabled || tone === 'mono'}
      style={[{ borderRadius: r }, style]}
    >
      {children}
    </BeamEngine>
  )
}

export default BorderBeam

import { View } from 'react-native'
import { BorderBeam as WebBeam } from 'border-beam'
import { useMotion, useTheme } from '@ondai/tokens/react'
import type { BorderBeamProps } from './border-beam'

export type { BorderBeamProps } from './border-beam'

const LAP = { md: 2.6, sm: 2.2, line: 3.4, 'pulse-inner': 2.6, 'pulse-outside': 2.6 } as const

/** Web: libraries.dev's own CSS border beam (MIT), with the same Ondai defaults as the native Skia port. */
export function BorderBeam({ children, active = true, tone = 'colorful', size = 'md', radius = 'lg', strength = 1, style }: BorderBeamProps) {
  const t = useTheme()
  const motion = useMotion()
  const r = typeof radius === 'number' ? radius : t.radii[radius]
  return (
    <View style={[{ borderRadius: r }, style]}>
      <WebBeam
        active={active}
        size={size}
        colorVariant={tone}
        theme={t.scheme}
        borderRadius={r}
        strength={strength}
        duration={motion.enabled ? LAP[size] : 1e9}
        staticColors={!motion.enabled || tone === 'mono'}
      >
        {children}
      </WebBeam>
    </View>
  )
}

export default BorderBeam

// Vendored from border-beam-native by Jakub Antalik (MIT, see LICENSE), github.com/Jakubantalik/Libraries.dev @ bad6322.
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { AccessibilityInfo, View, useColorScheme, type LayoutChangeEvent } from 'react-native';
import { useClock } from '@shopify/react-native-skia';
import {
  Easing,
  runOnJS,
  useSharedValue,
  withTiming,
} from 'react-native-reanimated';

import { beamSpec, sizePreset, themePreset } from './spec';
import { RotateBeam } from './RotateBeam';
import { LineBeam } from './LineBeam';
import { PulseBeam } from './PulseBeam';
import type { BorderBeamProps } from './types';
import { resolveTuning } from './tuning';

// CSS `ease` timing curve (web fade-in/out parity).
const CSS_EASE = Easing.bezier(0.25, 0.1, 0.25, 1);

/**
 * BorderBeam — animated border beam effect for React Native (Skia).
 *
 * ```tsx
 * <BorderBeam size="md" colorVariant="ocean" borderRadius={16}>
 *   <Card />
 * </BorderBeam>
 * ```
 */
export function BorderBeam({
  children,
  size = 'md',
  colorVariant = 'colorful',
  theme = 'dark',
  staticColors = false,
  duration,
  active = true,
  borderRadius,
  brightness,
  saturation,
  hueRange = 30,
  strength = 1,
  tuning,
  style,
  onActivate,
  onDeactivate,
}: BorderBeamProps) {
  const systemScheme = useColorScheme();
  const resolvedTheme: 'dark' | 'light' =
    theme === 'auto' ? (systemScheme === 'light' ? 'light' : 'dark') : theme;

  const [layout, setLayout] = useState({ width: 0, height: 0 });
  const [mounted, setMounted] = useState(active);
  const [reduceMotion, setReduceMotion] = useState(false);
  const fade = useSharedValue(0);
  const clock = useClock();
  const prevActive = useRef<boolean | null>(null);

  // Web parity: only the pulse family honors prefers-reduced-motion.
  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled().then(v => {
      if (alive) setReduceMotion(v);
    });
    const sub = AccessibilityInfo.addEventListener('reduceMotionChanged', setReduceMotion);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);

  const handleLayout = useCallback((e: LayoutChangeEvent) => {
    const { width, height } = e.nativeEvent.layout;
    setLayout(prev => (prev.width === width && prev.height === height ? prev : { width, height }));
  }, []);

  // Fade in/out with completion callbacks (web: 0.6 s in / 0.5 s out, ease).
  useEffect(() => {
    if (prevActive.current === active) return;
    prevActive.current = active;

    if (active) {
      setMounted(true);
      fade.value = withTiming(
        1,
        { duration: beamSpec.defaults.fadeInSeconds * 1000, easing: CSS_EASE },
        finished => {
          'worklet';
          if (finished && onActivate) runOnJS(onActivate)();
        }
      );
    } else {
      const unmount = () => {
        setMounted(false);
        onDeactivate?.();
      };
      fade.value = withTiming(
        0,
        { duration: beamSpec.defaults.fadeOutSeconds * 1000, easing: CSS_EASE },
        finished => {
          'worklet';
          if (finished) runOnJS(unmount)();
        }
      );
    }
  }, [active, fade, onActivate, onDeactivate]);

  const preset = sizePreset(size);
  const colors = themePreset(size, resolvedTheme);
  const isPulse = size === 'pulse-inner' || size === 'pulse-outside';
  const finalRadius = borderRadius ?? preset.borderRadius;
  const finalDuration =
    duration ??
    (size === 'line'
      ? beamSpec.defaults.duration.line
      : isPulse
        ? beamSpec.defaults.duration.pulse
        : beamSpec.defaults.duration.rotate);
  const finalBrightness = brightness ?? colors.brightness ?? beamSpec.defaults.brightnessFallback;
  const finalSaturation = saturation ?? colors.saturation;
  const finalStatic = colorVariant === 'mono' ? true : staticColors;
  const clampedStrength = Math.max(0, Math.min(1, strength));
  const resolvedTuning = useMemo(() => resolveTuning(tuning), [tuning]);
  // The line family caps the hue range at 13° (web parity).
  const finalHueRange = size === 'line' ? Math.min(hueRange, beamSpec.defaults.lineHueRangeCap) : hueRange;

  const hasSize = layout.width > 0 && layout.height > 0;

  return (
    <View style={style} onLayout={handleLayout}>
      {children}
      {mounted && hasSize && (size === 'sm' || size === 'md') && (
        <RotateBeam
          size={size}
          variant={colorVariant}
          theme={resolvedTheme}
          staticColors={finalStatic}
          duration={finalDuration}
          borderRadius={finalRadius}
          brightness={finalBrightness}
          saturation={finalSaturation}
          hueRange={finalHueRange}
          strength={clampedStrength}
          width={layout.width}
          height={layout.height}
          clock={clock}
          fade={fade}
        />
      )}
      {mounted && hasSize && size === 'line' && (
        <LineBeam
          variant={colorVariant}
          theme={resolvedTheme}
          staticColors={finalStatic}
          duration={finalDuration}
          borderRadius={finalRadius}
          brightness={finalBrightness}
          saturation={finalSaturation}
          hueRange={finalHueRange}
          strength={clampedStrength}
          width={layout.width}
          height={layout.height}
          clock={clock}
          fade={fade}
        />
      )}
      {mounted && hasSize && isPulse && (
        <PulseBeam
          size={size as 'pulse-inner' | 'pulse-outside'}
          variant={colorVariant}
          theme={resolvedTheme}
          staticColors={finalStatic}
          duration={finalDuration}
          borderRadius={finalRadius}
          brightness={finalBrightness}
          saturation={finalSaturation}
          strength={clampedStrength}
          width={layout.width}
          height={layout.height}
          clock={clock}
          fade={fade}
          reduceMotion={reduceMotion}
          tuning={resolvedTuning}
        />
      )}
    </View>
  );
}

export default BorderBeam;

// Vendored from border-beam-native by Jakub Antalik (MIT, see LICENSE), github.com/Jakubantalik/Libraries.dev @ bad6322.
/* eslint-disable */
// @ts-nocheck -- upstream code, kept as written; it is typed without noUncheckedIndexedAccess.
import { useMemo } from 'react';
import { StyleSheet } from 'react-native';
import {
  Canvas,
  Fill,
  Shader,
  Skia,
  Blur,
  Group,
  Paint,
} from '@shopify/react-native-skia';
import { useDerivedValue, type SharedValue } from 'react-native-reanimated';

import {
  beamSpec,
  borderPalette,
  smallPalette,
  parseCssColor,
  parsePercentPair,
  parsePixelPair,
  themePreset,
  sizePreset,
  type GradientBlob,
} from './spec';
import { composedFilterMatrix } from './colorMatrix';
import {
  ROTATE_LAYER_SKSL,
  MAX_BLOBS,
  MAX_BG_STOPS,
  MAX_MASK_STOPS,
  padTo,
} from './rotateShader';
import { pingPong } from './pulseDriver';
import type { BorderBeamColorVariant } from './types';

function makeRotateEffect() {
  const effect = Skia.RuntimeEffect.Make(ROTATE_LAYER_SKSL);
  if (!effect) {
    throw new Error('border-beam-native: failed to compile rotate SkSL effect');
  }
  return effect;
}

const rotateEffect = makeRotateEffect();

function blobFloats(
  blobs: GradientBlob[],
  sizeScale = 1,
  alphaOverride?: number
): number[] {
  const out: number[] = [];
  for (const blob of blobs) {
    const color = parseCssColor(blob.color);
    if (!color) continue;
    const pos = parsePercentPair(blob.pos);
    const radii = parsePixelPair(blob.size);
    // Web derivation rounds scaled sizes to whole px.
    const rx = sizeScale === 1 ? radii.w : Math.round(radii.w * sizeScale);
    const ry = sizeScale === 1 ? radii.h : Math.round(radii.h * sizeScale);
    out.push(rx, ry, pos.x, pos.y, color.r, color.g, color.b, alphaOverride ?? color.a);
  }
  return out;
}

function flattenStops(stops: number[][]): number[] {
  return stops.flatMap(([pos, alpha]) => [pos / 100, alpha]);
}

export interface RotateBeamProps {
  size: 'sm' | 'md';
  variant: BorderBeamColorVariant;
  theme: 'dark' | 'light';
  staticColors: boolean;
  duration: number;
  borderRadius: number;
  brightness: number;
  saturation: number;
  hueRange: number;
  strength: number;
  width: number;
  height: number;
  /** Milliseconds clock (Skia useClock). */
  clock: SharedValue<number>;
  /** 0..1 fade shared value (activate/deactivate). */
  fade: SharedValue<number>;
}

/**
 * The three rotate-family layers, mirroring the web z-order: inner glow (1),
 * stroke ring (2), blurred bloom ring (3).
 */
export function RotateBeam({
  size,
  variant,
  theme,
  staticColors,
  duration,
  borderRadius,
  brightness,
  saturation,
  hueRange,
  strength,
  width,
  height,
  clock,
  fade,
}: RotateBeamProps) {
  const rotate = beamSpec.rotate;
  const preset = sizePreset(size);
  const colors = themePreset(size, theme);
  const monoMul = variant === 'mono' ? beamSpec.defaults.monoOpacityMultiplier : 1;
  const isDark = theme === 'dark';

  const staticUniforms = useMemo(() => {
    const strokeBlobs =
      size === 'sm' ? blobFloats(smallPalette(variant).border) : blobFloats(borderPalette(variant));
    const innerBlobs =
      size === 'sm'
        ? blobFloats(smallPalette(variant).inner)
        : blobFloats(
            borderPalette(variant),
            rotate.innerGradientDerivation.sizeScale,
            variant === 'mono'
              ? rotate.innerGradientDerivation.monoAlpha
              : rotate.innerGradientDerivation.alpha
          );

    const themeKey = theme as 'dark' | 'light';
    const whiteStops = flattenStops(
      (rotate.whiteGradientStops as Record<string, number[][]>)[themeKey]
    );
    const bloomStops = flattenStops(
      (rotate.bloomGradientStops as Record<string, number[][]>)[themeKey]
    );
    const beamMask = flattenStops(rotate.beamMaskStops as number[][]);
    const smallMask = flattenStops(rotate.smallMaskStops as number[][]);
    const shadow = parseCssColor(colors.innerShadow) ?? { r: 0, g: 0, b: 0, a: 0 };

    return {
      strokeBlobs: padTo(strokeBlobs, MAX_BLOBS * 8),
      strokeBlobCount: strokeBlobs.length / 8,
      innerBlobs: padTo(innerBlobs, MAX_BLOBS * 8),
      innerBlobCount: innerBlobs.length / 8,
      whiteStops: padTo(whiteStops, MAX_BG_STOPS * 2),
      whiteStopCount: whiteStops.length,
      bloomStops: padTo(bloomStops, MAX_BG_STOPS * 2),
      bloomStopCount: bloomStops.length,
      beamMask: padTo(beamMask, MAX_MASK_STOPS * 2),
      beamMaskCount: beamMask.length,
      smallMask: padTo(smallMask, MAX_MASK_STOPS * 2),
      smallMaskCount: smallMask.length,
      shadow: [shadow.r, shadow.g, shadow.b, shadow.a],
      shadowBlur: size === 'sm' ? rotate.innerShadowBlur.sm : rotate.innerShadowBlur.md,
      emptyBlobs: padTo([], MAX_BLOBS * 8),
      emptyStops: padTo([], MAX_BG_STOPS * 2),
      emptyMask: padTo([], MAX_MASK_STOPS * 2),
    };
  }, [size, variant, theme, colors.innerShadow, rotate]);

  const hueShiftPeriod = beamSpec.defaults.rotateHueShiftPeriod;

  // Per-frame values, computed on the UI thread.
  const angle = useDerivedValue(() => {
    'worklet';
    return ((clock.value / 1000) / duration) % 1;
  }, [duration]);

  const filterMatrix = useDerivedValue(() => {
    'worklet';
    // Web parity: with staticColors the CSS stroke/inner layers have NO filter
    // at all — brightness/saturate exist only inside the hue-shift keyframes.
    if (staticColors) return [1, 0, 0, 0, 1, 0, 0, 0, 1];
    const t = clock.value / 1000;
    const hue = -hueRange + 2 * hueRange * pingPong(t / hueShiftPeriod);
    return composedFilterMatrix(hue, brightness, saturation);
  }, [staticColors, hueRange, brightness, saturation, hueShiftPeriod]);

  // Bloom filter has no hue-rotate on the web (static brightness/saturate).
  const bloomMatrix = useMemo(
    () => composedFilterMatrix(0, brightness, saturation),
    [brightness, saturation]
  );

  const baseLayer = useMemo(
    () => ({
      uSize: [width, height],
      uRadius: borderRadius,
      uBorderWidth: preset.borderWidth,
    }),
    [width, height, borderRadius, preset.borderWidth]
  );

  const s = staticUniforms;

  const innerUniforms = useDerivedValue(() => {
    'worklet';
    return {
      ...baseLayer,
      uAngle: angle.value,
      uKind: 1,
      uEdgeMaskPx: size === 'md' ? rotate.innerEdgeMaskPx : 0,
      uBlobs: s.innerBlobs,
      uBlobCount: s.innerBlobCount,
      uBg: s.emptyStops,
      uBgCount: 0,
      uBgIsBlack: 0,
      uMask: size === 'sm' ? s.smallMask : s.beamMask,
      uMaskCount: size === 'sm' ? s.smallMaskCount : s.beamMaskCount,
      uCM: filterMatrix.value,
      uOpacity: fade.value * strength * monoMul * colors.innerOpacity,
      uShadowColor: s.shadow,
      uShadowBlur: s.shadowBlur,
    };
  }, [baseLayer, size, s, strength, monoMul, colors.innerOpacity]);

  const strokeUniforms = useDerivedValue(() => {
    'worklet';
    return {
      ...baseLayer,
      uAngle: angle.value,
      uKind: 0,
      uEdgeMaskPx: 0,
      uBlobs: s.strokeBlobs,
      uBlobCount: s.strokeBlobCount,
      uBg: s.whiteStops,
      uBgCount: s.whiteStopCount,
      uBgIsBlack: isDark ? 0 : 1,
      uMask: s.beamMask,
      uMaskCount: s.beamMaskCount,
      uCM: filterMatrix.value,
      uOpacity: fade.value * strength * monoMul * colors.strokeOpacity,
      uShadowColor: [0, 0, 0, 0],
      uShadowBlur: 0,
    };
  }, [baseLayer, s, isDark, strength, monoMul, colors.strokeOpacity]);

  const bloomUniforms = useDerivedValue(() => {
    'worklet';
    return {
      ...baseLayer,
      uAngle: angle.value,
      uKind: 2,
      uEdgeMaskPx: 0,
      uBlobs: s.emptyBlobs,
      uBlobCount: 0,
      uBg: s.bloomStops,
      uBgCount: s.bloomStopCount,
      uBgIsBlack: isDark ? 0 : 1,
      uMask: s.emptyMask,
      uMaskCount: 0,
      uCM: bloomMatrix,
      uOpacity: fade.value * strength * monoMul * colors.bloomOpacity,
      uShadowColor: [0, 0, 0, 0],
      uShadowBlur: 0,
    };
  }, [baseLayer, s, isDark, strength, monoMul, colors.bloomOpacity, bloomMatrix]);

  if (width <= 0 || height <= 0) return null;

  return (
    <Canvas pointerEvents="none" style={StyleSheet.absoluteFill}>
      {/* Inner glow (z1) */}
      <Fill>
        <Shader source={rotateEffect} uniforms={innerUniforms} />
      </Fill>
      {/* Stroke ring (z2) */}
      <Fill>
        <Shader source={rotateEffect} uniforms={strokeUniforms} />
      </Fill>
      {/* Bloom ring (z3) — CSS blur(8px) is a Gaussian with stdDev 8, which is
          what Skia's Blur sigma expects, so the value maps 1:1. */}
      <Group
        layer={
          <Paint>
            <Blur blur={rotate.bloomBlurPx} />
          </Paint>
        }
      >
        <Fill>
          <Shader source={rotateEffect} uniforms={bloomUniforms} />
        </Fill>
      </Group>
    </Canvas>
  );
}

// Vendored from border-beam-native by Jakub Antalik (MIT, see LICENSE), github.com/Jakubantalik/Libraries.dev @ bad6322.
/* eslint-disable */
// @ts-nocheck -- upstream code, kept as written; it is typed without noUncheckedIndexedAccess.
import { useMemo } from 'react';
import { StyleSheet } from 'react-native';
import { Canvas, Fill, Shader, Skia, Blur, Group, Paint } from '@shopify/react-native-skia';
import { useDerivedValue, type SharedValue } from 'react-native-reanimated';

import { beamSpec, parseCssColor, sizePreset, themePreset } from './spec';
import { composedFilterMatrix } from './colorMatrix';
import {
  BLOB_LAYER_SKSL,
  BLOB_FLOATS,
  MAX_LAYER_BLOBS,
  NO_RADIAL,
  simpleBlob,
  stopsBlob,
} from './blobShader';
import { padTo } from './rotateShader';
import { lineFrameValues, multValue, pingPongWorklet, type LineKeyframeTables } from './lineDriver';
import type { BorderBeamColorVariant } from './types';

function makeBlobEffect() {
  const effect = Skia.RuntimeEffect.Make(BLOB_LAYER_SKSL);
  if (!effect) {
    throw new Error('border-beam-native: failed to compile blob SkSL effect');
  }
  return effect;
}

export const blobEffect = makeBlobEffect();

interface LineBlobDef {
  color: { r: number; g: number; b: number; a: number };
  sizeW: number;
  sizeH: number;
  offsetX: number;
  offsetY: number;
}

interface BloomGradientDef {
  xPct: number | null;
  yOffPx: number;
  w: { base: number; mult: string };
  h: { base: number; mult: string };
  stops: { r: number; g: number; b: number; a: number; pos: number }[];
}

export interface LineBeamProps {
  variant: BorderBeamColorVariant;
  theme: 'dark' | 'light';
  staticColors: boolean;
  duration: number;
  borderRadius: number;
  brightness: number;
  saturation: number;
  hueRange: number; // already capped at 13 by BorderBeam
  strength: number;
  width: number;
  height: number;
  clock: SharedValue<number>;
  fade: SharedValue<number>;
}

/**
 * The `line` family: bottom traveling glow with breathe and spike animations.
 * Layers mirror the web z-order: inner (1), stroke band (2), bloom (3).
 */
export function LineBeam({
  variant,
  theme,
  staticColors,
  duration,
  borderRadius,
  brightness,
  saturation,
  hueRange,
  strength,
  width,
  height,
  clock,
  fade,
}: LineBeamProps) {
  const spec = beamSpec;
  const preset = sizePreset('line');
  const colors = themePreset('line', theme);
  const isDark = theme === 'dark';

  const tables = spec.line.keyframes as unknown as LineKeyframeTables;

  const staticData = useMemo(() => {
    const linePalette = (spec.palettes.line as Record<string, Record<string, Omit<LineBlobDef, 'color'>[] & { color?: string }[]>>)[
      variant
    ][theme] as unknown as { color: string; sizeW: number; sizeH: number; offsetX: number; offsetY: number }[];
    const innerPalette = (spec.palettes.lineInner as Record<string, { color: string; sizeW: number; sizeH: number; offsetX: number; offsetY: number }[]>)[
      variant
    ];
    const bloom = (spec.line.bloomGradients as unknown as Record<string, Record<string, BloomGradientDef[]>>)[
      variant
    ][theme];

    const parse = (arr: { color: string; sizeW: number; sizeH: number; offsetX: number; offsetY: number }[]): LineBlobDef[] =>
      arr.map(e => ({
        color: parseCssColor(e.color) ?? { r: 1, g: 1, b: 1, a: 1 },
        sizeW: e.sizeW,
        sizeH: e.sizeH,
        offsetX: e.offsetX,
        offsetY: e.offsetY,
      }));

    const wh = (spec.line.whiteHighlight as Record<string, { w: number; h: number; yOffset: number; stops: number[][]; onBlack?: boolean }>)[
      theme
    ];

    return {
      strokeBlobDefs: parse(linePalette),
      innerBlobDefs: parse(innerPalette),
      bloomDefs: bloom,
      whiteHighlight: wh,
      shadow: parseCssColor(colors.innerShadow) ?? { r: 0, g: 0, b: 0, a: 0 },
    };
  }, [spec, variant, theme, colors.innerShadow]);

  const mask = spec.line.beamMaskEllipse as { w: number; h: number; softStop: number[] };
  const bloomMask = spec.line.bloomMaskEllipse as { w: number; h: number; softStop: number[] };
  const hueShiftPeriod = spec.defaults.rotateHueShiftPeriod;
  const bloomHuePeriod = spec.defaults.lineBloomHueShiftPeriod;
  const bloomHueBonus = spec.defaults.lineBloomHueRangeBonus;

  const s = staticData;

  // ── Per-frame uniforms (UI thread) ──

  const base = useMemo(
    () => ({
      uSize: [width, height],
      uRectOrigin: [0, 0],
      uRectSize: [width, height],
      uRadius: borderRadius,
      uBorderWidth: preset.borderWidth,
    }),
    [width, height, borderRadius, preset.borderWidth]
  );

  const strokeUniforms = useDerivedValue(() => {
    'worklet';
    const t = clock.value / 1000;
    const v = lineFrameValues(tables, t, duration);
    // Web parity: staticColors ⇒ no filter on the line layers at all.
    const cm = staticColors
      ? [1, 0, 0, 0, 1, 0, 0, 0, 1]
      : composedFilterMatrix(
          -hueRange + 2 * hueRange * pingPongWorklet(t / hueShiftPeriod),
          brightness,
          saturation
        );
    const bx = v.x * width;

    const blobs: number[] = [];
    // White traveling highlight is the FIRST background (on top).
    const wh = s.whiteHighlight;
    const whColor = wh.onBlack ? 0 : 1;
    blobs.push(
      ...stopsBlob(
        wh.w * v.w,
        wh.h * v.h,
        bx,
        height + wh.yOffset,
        wh.stops.map(([pos, a]) => ({
          r: whColor * 255, g: whColor * 255, b: whColor * 255, a, pos: pos / 100,
        }))
      )
    );
    for (const e of s.strokeBlobDefs) {
      blobs.push(
        ...simpleBlob(
          e.sizeW * v.w, e.sizeH * v.h,
          bx + e.offsetX, height + e.offsetY,
          e.color.r, e.color.g, e.color.b, e.color.a
        )
      );
    }

    return {
      ...base,
      uGeomKind: 0,
      uEdgeMaskPx: 0,
      uRadial: [bx, height, mask.w * v.w, mask.h * v.h, mask.softStop[0] / 100, mask.softStop[1], 1],
      uBlobs: padTo(blobs, MAX_LAYER_BLOBS * BLOB_FLOATS),
      uBlobCount: blobs.length / BLOB_FLOATS,
      uCM: cm,
      uOpacity: fade.value * v.edge * strength * colors.strokeOpacity,
    };
  }, [base, s, tables, duration, staticColors, hueRange, brightness, saturation, strength, colors.strokeOpacity, width, height]);

  const innerUniforms = useDerivedValue(() => {
    'worklet';
    const t = clock.value / 1000;
    const v = lineFrameValues(tables, t, duration);
    // Web parity: staticColors ⇒ no filter on the line layers at all.
    const cm = staticColors
      ? [1, 0, 0, 0, 1, 0, 0, 0, 1]
      : composedFilterMatrix(
          -hueRange + 2 * hueRange * pingPongWorklet(t / hueShiftPeriod),
          brightness,
          saturation
        );
    const bx = v.x * width;

    const blobs: number[] = [];
    for (const e of s.innerBlobDefs) {
      blobs.push(
        ...simpleBlob(
          e.sizeW * v.w, e.sizeH * v.h,
          bx + e.offsetX, height - Math.abs(e.offsetY),
          e.color.r, e.color.g, e.color.b, e.color.a
        )
      );
    }

    return {
      ...base,
      uGeomKind: 1,
      uEdgeMaskPx: beamSpec.rotate.innerEdgeMaskPx,
      uRadial: [bx, height, mask.w * v.w, mask.h * v.h, mask.softStop[0] / 100, mask.softStop[1], 1],
      uBlobs: padTo(blobs, MAX_LAYER_BLOBS * BLOB_FLOATS),
      uBlobCount: blobs.length / BLOB_FLOATS,
      uCM: cm,
      uOpacity: fade.value * v.edge * strength * colors.innerOpacity,
    };
  }, [base, s, tables, duration, staticColors, hueRange, brightness, saturation, strength, colors.innerOpacity, width, height]);

  const bloomUniforms = useDerivedValue(() => {
    'worklet';
    const t = clock.value / 1000;
    const v = lineFrameValues(tables, t, duration);
    // Bloom hue swings ±(hueRange+10) over 8 s on the web; staticColors ⇒ no
    // filter (mono keeps only its 6px blur, applied at the layer level).
    const cm = staticColors
      ? [1, 0, 0, 0, 1, 0, 0, 0, 1]
      : composedFilterMatrix(
          -(hueRange + bloomHueBonus) + 2 * (hueRange + bloomHueBonus) * pingPongWorklet(t / bloomHuePeriod),
          brightness,
          saturation
        );
    const bx = v.x * width;

    const blobs: number[] = [];
    for (const g of s.bloomDefs) {
      const cx = g.xPct != null ? (g.xPct / 100) * width : bx;
      blobs.push(
        ...stopsBlob(
          g.w.base * multValue(g.w.mult, v),
          g.h.base * multValue(g.h.mult, v),
          cx,
          height + g.yOffPx,
          g.stops
        )
      );
    }

    return {
      ...base,
      uGeomKind: 1,
      uEdgeMaskPx: 0,
      uRadial: [bx, height, bloomMask.w * v.w, bloomMask.h * v.h, bloomMask.softStop[0] / 100, bloomMask.softStop[1], 1],
      uBlobs: padTo(blobs, MAX_LAYER_BLOBS * BLOB_FLOATS),
      uBlobCount: blobs.length / BLOB_FLOATS,
      uCM: cm,
      uOpacity: fade.value * v.edge * strength * colors.bloomOpacity,
    };
  }, [base, s, tables, duration, staticColors, hueRange, brightness, saturation, strength, colors.bloomOpacity, width, height]);

  // Web parity: the animated bloom filter includes blur(8px); mono-with-static
  // colors gets a base blur(6px); colorful static colors gets no blur.
  const bloomBlur = staticColors
    ? variant === 'mono'
      ? (spec.line.monoBloomExtraBlurPx as number)
      : 0
    : (spec.line.bloomBlurPx as number);

  if (width <= 0 || height <= 0) return null;

  return (
    <Canvas pointerEvents="none" style={StyleSheet.absoluteFill}>
      {/* Inner glow (z1) */}
      <Fill>
        <Shader source={blobEffect} uniforms={innerUniforms} />
      </Fill>
      {/* Stroke band (z2) */}
      <Fill>
        <Shader source={blobEffect} uniforms={strokeUniforms} />
      </Fill>
      {/* Bloom (z3) */}
      {bloomBlur > 0 ? (
        <Group
          layer={
            <Paint>
              <Blur blur={bloomBlur} />
            </Paint>
          }
        >
          <Fill>
            <Shader source={blobEffect} uniforms={bloomUniforms} />
          </Fill>
        </Group>
      ) : (
        <Fill>
          <Shader source={blobEffect} uniforms={bloomUniforms} />
        </Fill>
      )}
    </Canvas>
  );
}

// Vendored from border-beam-native by Jakub Antalik (MIT, see LICENSE), github.com/Jakubantalik/Libraries.dev @ bad6322.
/* eslint-disable */
// @ts-nocheck -- upstream code, kept as written; it is typed without noUncheckedIndexedAccess.
import { useMemo } from 'react';
import { StyleSheet } from 'react-native';
import { Canvas, Fill, Shader, Blur, Group, Paint } from '@shopify/react-native-skia';
import { useDerivedValue, type SharedValue } from 'react-native-reanimated';

import {
  beamSpec,
  borderPalette,
  parseCssColor,
  parsePercentPair,
  parsePixelPair,
  sizePreset,
  themePreset,
  type Oscillator,
} from './spec';
import { composedFilterMatrix } from './colorMatrix';
import { BLOB_FLOATS, MAX_LAYER_BLOBS, NO_RADIAL } from './blobShader';
import { padTo } from './rotateShader';
import { blobEffect } from './LineBeam';
import { oscillatorValue, pulseHueDegrees } from './pulseDriver';
import type { BorderBeamColorVariant } from './types';
import { NO_TUNING, type ResolvedTuning } from './tuning';

interface PulseTableEntry {
  ci: number;
  region: number;
  quad: string;
  w: number;
  h: number;
  x?: string;
  y?: string;
}

/** Static description of one pulse blob, resolved per-frame with oscillators. */
interface PulseBlobDef {
  region: number; // 1-3 size/drift region; 0 = static (corner accents)
  quad: string;   // opacity quadrant
  w: number;      // base radius x (reference geometry px)
  h: number;
  xFrac: number;  // position, fraction of the layer box
  yFrac: number;
  r: number; g: number; b: number; // 0..1
  a: number;      // base alpha (corners); ring/table blobs use the quad opacity
  fadeEnd: number;
}

const DEFAULT_PULSE_DURATION = 2.3;

function defsFromRing(variant: BorderBeamColorVariant): PulseBlobDef[] {
  const ringMap = beamSpec.pulse.ringMap as { region: number; quad: string }[];
  return borderPalette(variant).map((blob, i) => {
    const c = parseCssColor(blob.color) ?? { r: 1, g: 1, b: 1, a: 1 };
    const pos = parsePercentPair(blob.pos);
    const size = parsePixelPair(blob.size);
    return {
      region: ringMap[i].region,
      quad: ringMap[i].quad,
      w: size.w,
      h: size.h,
      xFrac: pos.x,
      yFrac: pos.y,
      r: c.r, g: c.g, b: c.b, a: c.a,
      fadeEnd: 1,
    };
  });
}

function defsFromTable(variant: BorderBeamColorVariant, table: PulseTableEntry[]): PulseBlobDef[] {
  const palette = borderPalette(variant);
  return table.map(e => {
    const src = palette[e.ci];
    const c = parseCssColor(src.color) ?? { r: 1, g: 1, b: 1, a: 1 };
    const srcPos = parsePercentPair(src.pos);
    return {
      region: e.region,
      quad: e.quad,
      w: e.w,
      h: e.h,
      xFrac: e.x != null ? parseFloat(e.x) / 100 : srcPos.x,
      yFrac: e.y != null ? parseFloat(e.y) / 100 : srcPos.y,
      r: c.r, g: c.g, b: c.b, a: c.a,
      fadeEnd: 1,
    };
  });
}

/** pulse-inner ::before: ring gradients at reduced sizes + 4 corner accents. */
function innerLayerDefs(variant: BorderBeamColorVariant, isDark: boolean): PulseBlobDef[] {
  const innerSizes = beamSpec.pulse.innerSizes as number[][];
  const ring = defsFromRing(variant).map((d, i) => ({
    ...d,
    w: innerSizes[i][0],
    h: innerSizes[i][1],
  }));
  const accent = beamSpec.pulse.innerCornerAccent as {
    sizePx: number;
    alpha: { dark: number; light: number };
    fadeStop: number;
  };
  const cornerColor = isDark ? 1 : 0;
  const cornerAlpha = isDark ? accent.alpha.dark : accent.alpha.light;
  const corners: [number, number, string][] = [
    [0, 0, 'tl'], [1, 0, 'tr'], [0, 1, 'bl'], [1, 1, 'br'],
  ];
  const cornerDefs: PulseBlobDef[] = corners.map(([x, y, quad]) => ({
    region: 0,
    quad,
    w: accent.sizePx,
    h: accent.sizePx,
    xFrac: x,
    yFrac: y,
    r: cornerColor, g: cornerColor, b: cornerColor,
    a: cornerAlpha,
    fadeEnd: accent.fadeStop / 100,
  }));
  return [...ring, ...cornerDefs];
}

/** Geometry of one layer's box within the canvas. */
interface LayerBox {
  originX: number;
  originY: number;
  w: number;
  h: number;
  radius: number;
  geomKind: number; // 0 ring band, 1 fill, 2 none
  borderWidth: number;
  edgeMaskPx: number;
}

export interface PulseBeamProps {
  size: 'pulse-inner' | 'pulse-outside';
  variant: BorderBeamColorVariant;
  theme: 'dark' | 'light';
  staticColors: boolean;
  duration: number;
  borderRadius: number;
  brightness: number;
  saturation: number;
  strength: number;
  width: number;
  height: number;
  clock: SharedValue<number>;
  fade: SharedValue<number>;
  reduceMotion: boolean;
  tuning?: ResolvedTuning;
}

/**
 * Pulse family — breathing glow, no rotation.
 *
 * `pulse-inner`: everything clipped inside the element (one overlay canvas).
 * `pulse-outside`: core + bloom bloom OUTWARD behind the element (a canvas
 * extended `bloomInsetPx` on each side at zIndex -1 — the wrapped child must
 * be opaque, same requirement as the web version), plus a 1px stroke ring
 * overlay above the content.
 */
export function PulseBeam(props: PulseBeamProps) {
  const { size, variant, theme, width, height } = props;
  const isOutside = size === 'pulse-outside';
  const isDark = theme === 'dark';
  const spec = beamSpec;
  const preset = sizePreset(size);

  const oc = spec.pulse.outsideConstants as {
    glowScale: { x: number; y: number };
    glowBlurPx: { dark: number; light: number };
    bloomBlurPx: { dark: number; light: number };
    coreInsetPx: number;
    bloomInsetPx: number;
    referenceSize: { w: number; h: number };
    scaleClamp: { min: number; max: number };
  };

  const tuning = props.tuning ?? NO_TUNING;
  // The web clamps the *measured* ratio and applies --pulse-glow-boost on top,
  // so the boost is deliberately outside the clamp.
  const clampScale = (v: number) => Math.min(oc.scaleClamp.max, Math.max(oc.scaleClamp.min, v));
  const glowSx = isOutside ? clampScale(width / oc.referenceSize.w) * tuning.glowBoost : 1;
  const glowSy = isOutside ? clampScale(height / oc.referenceSize.h) * tuning.glowBoost : 1;

  const pad = isOutside ? oc.bloomInsetPx : 0;
  const canvasW = width + pad * 2;
  const canvasH = height + pad * 2;

  const defs = useMemo(
    () => ({
      stroke: isOutside
        ? defsFromTable(variant, spec.pulse.outerCore as PulseTableEntry[])
        : defsFromRing(variant),
      inner: isOutside
        ? defsFromTable(variant, spec.pulse.outerCore as PulseTableEntry[])
        : innerLayerDefs(variant, isDark),
      bloom: defsFromTable(
        variant,
        (isOutside ? spec.pulse.outerBloom : spec.pulse.innerBloom) as PulseTableEntry[]
      ),
    }),
    [spec, variant, isOutside, isDark]
  );

  const boxes: Record<'stroke' | 'inner' | 'bloom', LayerBox> = {
    // ::after — 1px ring band on the element edge.
    stroke: {
      originX: pad, originY: pad, w: width, h: height,
      radius: props.borderRadius, geomKind: 0,
      borderWidth: isOutside ? 1 : preset.borderWidth,
      edgeMaskPx: 0,
    },
    // ::before — element box (inner) or the +10px core box (outside).
    inner: isOutside
      ? {
          originX: pad - oc.coreInsetPx, originY: pad - oc.coreInsetPx,
          w: width + oc.coreInsetPx * 2, h: height + oc.coreInsetPx * 2,
          radius: props.borderRadius + oc.coreInsetPx, geomKind: 1,
          borderWidth: 1, edgeMaskPx: 0,
        }
      : {
          originX: 0, originY: 0, w: width, h: height,
          radius: props.borderRadius, geomKind: 1,
          borderWidth: preset.borderWidth,
          edgeMaskPx: spec.rotate.innerEdgeMaskPx,
        },
    // bloom — +30px box fill (outside) or 1px ring band (inner).
    bloom: isOutside
      ? {
          originX: 0, originY: 0, w: canvasW, h: canvasH,
          radius: props.borderRadius + oc.bloomInsetPx, geomKind: 1,
          borderWidth: 1, edgeMaskPx: 0,
        }
      : {
          originX: 0, originY: 0, w: width, h: height,
          radius: props.borderRadius, geomKind: 0,
          borderWidth: preset.borderWidth, edgeMaskPx: 0,
        },
  };

  const uniforms = usePulseUniforms(props, defs, boxes, { glowSx, glowSy, canvasW, canvasH }, tuning);

  const glowBlur =
    tuning.coreBlur ?? (isOutside ? (isDark ? oc.glowBlurPx.dark : oc.glowBlurPx.light) : 0);
  const bloomBlur =
    tuning.bloomBlur ??
    (isOutside
      ? isDark
        ? oc.bloomBlurPx.dark
        : oc.bloomBlurPx.light
      : (spec.pulse.innerBloomBlurPx as number));

  // pulse-outside core/bloom carry `transform: scale(0.95, 0.9)` about center.
  const glowTransform = [
    { translateX: canvasW / 2 },
    { translateY: canvasH / 2 },
    { scaleX: oc.glowScale.x },
    { scaleY: oc.glowScale.y },
    { translateX: -canvasW / 2 },
    { translateY: -canvasH / 2 },
  ];

  if (width <= 0 || height <= 0) return null;

  if (!isOutside) {
    return (
      <Canvas pointerEvents="none" style={StyleSheet.absoluteFill}>
        <Fill>
          <Shader source={blobEffect} uniforms={uniforms.inner} />
        </Fill>
        <Fill>
          <Shader source={blobEffect} uniforms={uniforms.stroke} />
        </Fill>
        <Group layer={<Paint><Blur blur={bloomBlur} /></Paint>}>
          <Fill>
            <Shader source={blobEffect} uniforms={uniforms.bloom} />
          </Fill>
        </Group>
      </Canvas>
    );
  }

  return (
    <>
      {/* Glow behind the content (web z-index -1). Child must be opaque. */}
      <Canvas
        pointerEvents="none"
        style={{
          position: 'absolute',
          left: -pad,
          top: -pad,
          width: canvasW,
          height: canvasH,
          zIndex: -1,
        }}
      >
        <Group transform={glowTransform} layer={<Paint><Blur blur={bloomBlur} /></Paint>}>
          <Fill>
            <Shader source={blobEffect} uniforms={uniforms.bloom} />
          </Fill>
        </Group>
        <Group transform={glowTransform} layer={<Paint><Blur blur={glowBlur} /></Paint>}>
          <Fill>
            <Shader source={blobEffect} uniforms={uniforms.inner} />
          </Fill>
        </Group>
      </Canvas>
      {/* 1px stroke ring above the content. */}
      <Canvas pointerEvents="none" style={StyleSheet.absoluteFill}>
        <Fill>
          <Shader source={blobEffect} uniforms={uniforms.stroke} />
        </Fill>
      </Canvas>
    </>
  );
}

// ── Per-frame uniform derivation ─────────────────────────────────────────────

function usePulseUniforms(
  props: PulseBeamProps,
  defs: { stroke: PulseBlobDef[]; inner: PulseBlobDef[]; bloom: PulseBlobDef[] },
  boxes: Record<'stroke' | 'inner' | 'bloom', LayerBox>,
  geo: { glowSx: number; glowSy: number; canvasW: number; canvasH: number },
  tuning: ResolvedTuning
) {
  const {
    size, variant, theme, staticColors, duration,
    brightness, saturation, strength, clock, fade, reduceMotion,
  } = props;
  const spec = beamSpec;
  const isOutside = size === 'pulse-outside';
  const colors = themePreset(size, theme);
  const monoMul = variant === 'mono' ? spec.defaults.monoOpacityMultiplier : 1;

  const section = (isOutside ? spec.pulse.outside : spec.pulse.inner) as Record<
    string,
    { oscillators: Oscillator[]; frozenBloomAlpha: number }
  >;
  const themeSection = section[theme];
  const oscillators = themeSection.oscillators;
  const durationScale = duration / DEFAULT_PULSE_DURATION;
  const huePeriod = (spec.pulse.huePeriod as Record<string, number>)[size];
  const sx = isOutside ? geo.glowSx : 1;
  const sy = isOutside ? geo.glowSy : 1;

  const makeLayer = (
    layerDefs: PulseBlobDef[],
    box: LayerBox,
    layerOpacity: number,
    frozenAlpha: number | null,
    opacityMul: number,
    isGlowLayer: boolean
  ) =>
    useDerivedValue(() => {
      'worklet';
      const t = reduceMotion ? 0 : clock.value / 1000;
      const osc: Record<string, number> = {};
      for (let i = 0; i < oscillators.length; i++) {
        osc[oscillators[i].prop] = reduceMotion
          ? oscillators[i].a
          : oscillatorValue(oscillators[i], t, durationScale);
      }
      const hue = staticColors || reduceMotion ? 0 : pulseHueDegrees(t, huePeriod);
      // Glow layers take their own brightness/saturate overrides but keep the
      // shared hue rotation, so halo and ring stay color-synced.
      const cm = composedFilterMatrix(
        hue,
        isGlowLayer && tuning.glowBrightness != null ? tuning.glowBrightness : brightness,
        isGlowLayer && tuning.glowSaturate != null ? tuning.glowSaturate : saturation
      );

      const blobs: number[] = [];
      for (const d of layerDefs) {
        let rx: number;
        let ry: number;
        let cx: number;
        let cy: number;
        let alpha: number;
        if (frozenAlpha != null) {
          // Frozen bloom: literal geometry, time-averaged alpha (web parity —
          // the blurred bloom bitmap never re-rasterizes per frame).
          rx = d.w * sx;
          ry = d.h * sy;
          cx = box.originX + d.xFrac * box.w;
          cy = box.originY + d.yFrac * box.h;
          alpha = frozenAlpha;
        } else {
          const bw = d.region > 0 ? osc[`bw${d.region}`] ?? 1 : 1;
          const bh = d.region > 0 ? (osc[`bh${d.region}`] ?? 1) * (osc.bgh ?? 1) : 1;
          const dx = d.region > 0 ? osc[`bx${d.region}`] ?? 0 : 0;
          const dy = d.region > 0 ? osc[`by${d.region}`] ?? 0 : 0;
          const bop = osc[`bop-${d.quad}`] ?? 1;
          // Ring/table blobs replace their alpha with the quadrant opacity
          // (web withAlphaVar); static corner accents multiply their base.
          alpha = d.region === 0 ? d.a * bop : bop;
          rx = d.w * bw * sx;
          ry = d.h * bh * sy;
          cx = box.originX + d.xFrac * box.w + dx;
          cy = box.originY + d.yFrac * box.h + dy;
        }
        const end = d.fadeEnd;
        blobs.push(
          rx, ry, cx, cy, d.r, d.g, d.b, alpha,
          end / 3, alpha * (2 / 3), (2 * end) / 3, alpha / 3, end, 0
        );
      }

      return {
        uSize: [geo.canvasW, geo.canvasH],
        uRectOrigin: [box.originX, box.originY],
        uRectSize: [box.w, box.h],
        uRadius: box.radius,
        uBorderWidth: box.borderWidth,
        uGeomKind: box.geomKind,
        uEdgeMaskPx: box.edgeMaskPx,
        uRadial: NO_RADIAL,
        uBlobs: padTo(blobs, MAX_LAYER_BLOBS * BLOB_FLOATS),
        uBlobCount: blobs.length / BLOB_FLOATS,
        uCM: cm,
        uOpacity: fade.value * strength * monoMul * layerOpacity * opacityMul,
      };
    }, [layerDefs, box, oscillators, durationScale, staticColors, reduceMotion, brightness, saturation, strength, monoMul, layerOpacity, frozenAlpha, sx, sy, geo]);

  // On pulse-outside the inner/bloom layers are the outward glow; on
  // pulse-inner they are contained and keep the base filter.
  return {
    stroke: makeLayer(defs.stroke, boxes.stroke, colors.strokeOpacity, null, tuning.strokeOpacity, false),
    inner: makeLayer(defs.inner, boxes.inner, colors.innerOpacity, null, tuning.innerOpacity, isOutside),
    bloom: makeLayer(
      defs.bloom, boxes.bloom, colors.bloomOpacity,
      themeSection.frozenBloomAlpha, tuning.bloomOpacity, isOutside
    ),
  };
}

// Vendored from border-beam-native by Jakub Antalik (MIT, see LICENSE), github.com/Jakubantalik/Libraries.dev @ bad6322.
/**
 * SkSL runtime effect for the rotate-family beam layers — a direct translation
 * of BorderBeamKit's `BeamShaders.metal` (keep both in sync; see that file for
 * the CSS semantics being mirrored).
 *
 * Uniform arrays are fixed-size in SkSL; counts select the used prefix.
 * Blob layout: 8 floats each — [rx, ry, cxFrac, cyFrac, r, g, b, a].
 * Stop arrays: [pos 0..1, alpha] pairs.
 */
export const MAX_BLOBS = 12;
export const MAX_BG_STOPS = 16;
export const MAX_MASK_STOPS = 12;

export const ROTATE_LAYER_SKSL = `
const float PI = 3.14159265358979;

uniform float2 uSize;
uniform float uAngle;        // beam angle, fraction of a full turn 0..1
uniform float uRadius;
uniform float uBorderWidth;
uniform float uKind;         // 0 stroke ring, 1 inner glow, 2 bloom ring
uniform float uEdgeMaskPx;   // inner-layer edge fade; 0 = none
uniform float uBlobs[${MAX_BLOBS * 8}];
uniform float uBlobCount;
uniform float uBg[${MAX_BG_STOPS * 2}];
uniform float uBgCount;      // float count (pairs * 2)
uniform float uBgIsBlack;
uniform float uMask[${MAX_MASK_STOPS * 2}];
uniform float uMaskCount;    // float count (pairs * 2)
uniform float uCM[9];        // row-major 3x3 color matrix
uniform float uOpacity;
uniform float4 uShadowColor;
uniform float uShadowBlur;

float roundedRectSDF(float2 p, float2 halfSize, float radius) {
  float2 q = abs(p) - halfSize + radius;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - radius;
}

float conicFraction(float2 p, float2 center) {
  float2 d = p - center;
  float theta = atan(d.x, -d.y);   // 0 at top, +clockwise (y-down coords)
  return fract(theta / (2.0 * PI) + 1.0);
}

float bgStopsAlpha(float t) {
  int n = int(uBgCount) * 1 / 2;
  if (n == 0) { return 1.0; }
  float result = uBg[1];
  for (int i = 1; i < ${MAX_BG_STOPS}; i++) {
    if (i < n) {
      float p0 = uBg[2 * (i - 1)];
      float a0 = uBg[2 * (i - 1) + 1];
      float p1 = uBg[2 * i];
      float a1 = uBg[2 * i + 1];
      if (t > p0) {
        float f = p1 > p0 ? clamp((t - p0) / (p1 - p0), 0.0, 1.0) : 1.0;
        result = mix(a0, a1, f);
      }
    }
  }
  return result;
}

float maskStopsAlpha(float t) {
  int n = int(uMaskCount) * 1 / 2;
