/**
 * Typed access to the platform-neutral `beam-spec.json`, generated from the
 * web library (`npm run spec` in the repo root). To sync after a web update:
 * `npm run spec && cp spec/beam-spec.json ports/react-native/border-beam-native/src/`.
 */
import spec from './beam-spec.json';
import type { BorderBeamColorVariant, BorderBeamSize } from './types';

export interface GradientBlob {
  color: string;
  pos: string;
  size: string;
}

export interface ThemeColors {
  strokeOpacity: number;
  innerOpacity: number;
  bloomOpacity: number;
  innerShadow: string;
  saturation: number;
  brightness?: number;
  hairlineOpacity?: number;
}

export interface Oscillator {
  prop: string;
  a: number;
  b: number;
  period: number;
  delay: number;
  unit: string;
}

export const beamSpec = spec;

export function themePreset(size: BorderBeamSize, theme: 'dark' | 'light'): ThemeColors {
  return (spec.sizeThemePresets as Record<string, Record<string, ThemeColors>>)[size][theme];
}

export function sizePreset(size: BorderBeamSize): { borderRadius: number; borderWidth: number } {
  return (spec.sizePresets as Record<string, { borderRadius: number; borderWidth: number }>)[size];
}

export function borderPalette(variant: BorderBeamColorVariant): GradientBlob[] {
  return (spec.palettes.border as Record<string, { border: GradientBlob[] }>)[variant].border;
}

export function smallPalette(variant: BorderBeamColorVariant): { border: GradientBlob[]; inner: GradientBlob[] } {
  return (spec.palettes.small as Record<string, { border: GradientBlob[]; inner: GradientBlob[] }>)[variant];
}

// ── CSS value parsing (same semantics as BorderBeamKit/BeamSpec.swift) ──

export interface RGBA {
  r: number;
  g: number;
  b: number;
  a: number;
}

/** Parses "rgb(r, g, b)" / "rgba(r, g, b, a)" / "transparent" (0-1 channels). */
export function parseCssColor(css: string): RGBA | null {
  const s = css.trim();
  if (s === 'transparent') return { r: 0, g: 0, b: 0, a: 0 };
  const m = s.match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)\s*(?:,\s*([\d.]+)\s*)?\)$/);
  if (!m) return null;
  return {
    r: parseFloat(m[1]) / 255,
    g: parseFloat(m[2]) / 255,
    b: parseFloat(m[3]) / 255,
    a: m[4] != null ? parseFloat(m[4]) : 1,
  };
}

/** Parses "33% -7.4%" → { x: 0.33, y: -0.074 }. */
export function parsePercentPair(value: string): { x: number; y: number } {
  const parts = value.split(' ');
  const pct = (p: string) => parseFloat(p.replace('%', '')) / 100;
  return { x: pct(parts[0] ?? '0'), y: pct(parts[1] ?? '0') };
}

/** Parses "70px 40px" → { w: 70, h: 40 } (CSS explicit-size gradient RADII). */
export function parsePixelPair(value: string): { w: number; h: number } {
  const parts = value.split(' ');
  const px = (p: string) => parseFloat(p.replace('px', ''));
  return { w: px(parts[0] ?? '0'), h: px(parts[1] ?? '0') };
}

// Vendored from border-beam-native by Jakub Antalik (MIT, see LICENSE), github.com/Jakubantalik/Libraries.dev @ bad6322.
/**
 * Consumer tuning hooks — the React Native equivalent of the web library's CSS
 * custom properties (`--pulse-glow-boost`, `--beam-stroke-opacity`,
 * `--beam-core-blur`, `--beam-glow-brightness`, …), added in border-beam 1.3.0.
 * Mirrors BorderBeamKit's `BeamTuning` — keep the two in sync.
 *
 * They dial a beam's prominence up or down *proportionally* without replacing
 * the effect's internals. The web demo's `pulse-outside` preset runs
 * `glowBoost 1.05` with `1.71x` layer opacity, which is why an untuned beam
 * looks noticeably softer than the demo.
 */
export interface BeamTuning {
  /**
   * Proportional multiplier on the measured per-element glow scale
   * (`--pulse-glow-boost`). Affects the pulse family's blob geometry.
   * @default 1
   */
  glowBoost?: number;

  /**
   * Multipliers on the stroke / inner / bloom layer opacity
   * (`--beam-stroke-opacity` and friends). The final opacity is still clamped
   * to 1, exactly as the CSS `opacity` property clamps.
   * @default 1
   */
  strokeOpacity?: number;
  innerOpacity?: number;
  bloomOpacity?: number;

  /**
   * Blur radius overrides for the pulse-outside core and bloom layers
   * (`--beam-core-blur` / `--beam-bloom-blur`). Omit to keep the preset.
   */
  coreBlur?: number;
  bloomBlur?: number;

  /**
   * Brightness / saturation overrides for the outward glow layers only
   * (`--beam-glow-brightness` / `--beam-glow-saturate`). Omit to keep the
   * preset. These deliberately do not touch the stroke ring, so the tight ring
   * and the wide halo stay color-synced.
   */
  glowBrightness?: number;
  glowSaturate?: number;
}

/** Tuning with every hook resolved to a concrete value. */
export interface ResolvedTuning {
  glowBoost: number;
  strokeOpacity: number;
  innerOpacity: number;
  bloomOpacity: number;
  coreBlur?: number;
  bloomBlur?: number;
  glowBrightness?: number;
  glowSaturate?: number;
}

export const NO_TUNING: ResolvedTuning = {
  glowBoost: 1,
  strokeOpacity: 1,
  innerOpacity: 1,
  bloomOpacity: 1,
};

export function resolveTuning(t?: BeamTuning): ResolvedTuning {
  if (!t) return NO_TUNING;
  return {
    glowBoost: t.glowBoost ?? 1,
    strokeOpacity: t.strokeOpacity ?? 1,
    innerOpacity: t.innerOpacity ?? 1,
    bloomOpacity: t.bloomOpacity ?? 1,
    coreBlur: t.coreBlur,
    bloomBlur: t.bloomBlur,
    glowBrightness: t.glowBrightness,
    glowSaturate: t.glowSaturate,
  };
}

/**
 * The tuning the web demo applies to its `pulse-outside` card
 * (`.beam-host--pulse-outside-tuned` in demo/src/styles.css). Exported so
 * consumers can reproduce the demo's look, which is *not* the library default.
 */
export const WEB_DEMO_PULSE_PRESET: BeamTuning = {
  glowBoost: 1.05,
  strokeOpacity: 1.71,
  innerOpacity: 1.71,
  bloomOpacity: 1.71,
  glowBrightness: 1.3 * 1.71,
  glowSaturate: 1.2 * 1.71,
};

